WITH "set_ordered" AS (SELECT DISTINCT "t0"."branch_id" AS "key" FROM "sales"."orders" AS "t0" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') AND ("t0"."branch_id" IS NOT NULL)) SELECT COUNT(*) AS "branches" FROM "sales"."branches" AS "t0" WHERE ("t0"."branch_id" NOT IN (SELECT "key" FROM "set_ordered"))
